/**
 * What the SIMRS Khanza desktop app looks like: menu groups [A]–[T], the button
 * in each group, the form it opens, the access right that gates it, the tables
 * the form mentions, and the flows written under docs/khanza-app/flows/.
 *
 * Generated by `pnpm extract-khanza-app` (scripts/extract-khanza-app.ts) from
 * the Khanza source, so this is a snapshot tied to one commit, not to the live
 * database. Missing files give an empty map (same behaviour as SchemaDocs).
 */
import { Context, Effect, Layer } from "effect";
import { readdir, readFile } from "node:fs/promises";
import * as NodePath from "node:path";
import { AppDocPathConfig } from "../config.ts";

export interface AppMenu {
  /** "A/Registrasi". */
  readonly path: string;
  readonly label: string;
  readonly groupLetter: string;
  /** Short group name used in answers ("Rekam Medis"). */
  readonly groupName: string;
  readonly groupTitle: string;
  readonly button: string;
  readonly rights: ReadonlyArray<string>;
  readonly form: string | null;
}

interface AppShortcut {
  readonly path: string;
  readonly form: string | null;
}

interface AppToolbarEntry {
  readonly label: string;
  readonly form: string | null;
}

export interface AppForm {
  readonly name: string;
  /** Visible dialog header ("Data Resume Medis Pasien Rawat Inap"). */
  readonly title: string;
  readonly file: string;
  readonly package: string;
  readonly menus: ReadonlyArray<string>;
  readonly rights: ReadonlyArray<string>;
  /** Buttons inside the form ("Simpan", "Pindah", "Pulang"). */
  readonly actions: ReadonlyArray<string>;
  /** Right-click menu entries ("Obat → Input Resep Pulang"). */
  readonly popup: ReadonlyArray<AppShortcut>;
  readonly tables: { readonly read: ReadonlyArray<string>; readonly write: ReadonlyArray<string> };
}

export interface AppRight {
  readonly name: string;
  readonly menus: ReadonlyArray<string>;
  readonly forms: ReadonlyArray<string>;
}

export interface AppFlowStep {
  readonly title: string;
  /** `A/Registrasi (DlgReg)`, when the step names one. */
  readonly menu: string | null;
  readonly form: string | null;
  /** Tables the step mentions, as written in the doc. */
  readonly tables: string | null;
}

export interface AppFlow {
  readonly id: string;
  readonly title: string;
  readonly keywords: ReadonlyArray<string>;
  readonly menus: ReadonlyArray<string>;
  readonly forms: ReadonlyArray<string>;
  /** Path relative to the repository root, e.g. docs/khanza-app/flows/rawat-inap.md. */
  readonly file: string;
  readonly steps: ReadonlyArray<AppFlowStep>;
  /** Plain text of the doc, used for search. */
  readonly text: string;
}

/** Staff words that never appear as a menu label ("pindah kamar", "SEP"). */
export interface AppSynonym {
  readonly terms: ReadonlyArray<string>;
  readonly menus: ReadonlyArray<string>;
  readonly forms: ReadonlyArray<string>;
  readonly tables: ReadonlyArray<string>;
  /** Right-click item this phrase means, when it is a shortcut rather than a menu. */
  readonly shortcut?: string | null;
  readonly note: string;
}

export interface AppDocsService {
  readonly source: { readonly commit: string; readonly generatedAt: string; readonly root: string };
  readonly menus: ReadonlyArray<AppMenu>;
  readonly toolbar: ReadonlyArray<AppToolbarEntry>;
  readonly forms: ReadonlyArray<AppForm>;
  readonly rights: ReadonlyArray<AppRight>;
  readonly flows: ReadonlyArray<AppFlow>;
  readonly synonyms: ReadonlyArray<AppSynonym>;
}

export class AppDocs extends Context.Service<AppDocs, AppDocsService>()("simha/AppDocs") {}

const EMPTY: AppDocsService = {
  source: { commit: "unknown", generatedAt: "", root: "" },
  menus: [],
  toolbar: [],
  forms: [],
  rights: [],
  flows: [],
  synonyms: [],
};

const asString = (value: unknown): string | null => (typeof value === "string" ? value : null);
const asStringArray = (value: unknown): ReadonlyArray<string> =>
  Array.isArray(value) ? value.filter((v): v is string => typeof v === "string") : [];

const asRecord = (value: unknown): Record<string, unknown> | null =>
  typeof value === "object" && value !== null && !Array.isArray(value) ? (value as Record<string, unknown>) : null;

/** Rebuilds the graph from index.json, ignoring anything malformed. */
export const parseAppIndex = (text: string, repoRoot: string): AppDocsService => {
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    return EMPTY;
  }
  const root = asRecord(raw);
  if (root === null) return EMPTY;

  const source = asRecord(root.source) ?? {};
  const menus: AppMenu[] = [];
  const groups = Array.isArray(root.groups) ? root.groups : [];
  for (const group of groups) {
    const g = asRecord(group);
    if (g === null) continue;
    const letter = asString(g.letter) ?? "?";
    const groupTitle = asString(g.title) ?? "";
    const groupName = asString(g.name) ?? groupTitle;
    const entries = Array.isArray(g.entries) ? g.entries : [];
    for (const entry of entries) {
      const e = asRecord(entry);
      if (e === null) continue;
      const label = asString(e.label) ?? asString(e.button) ?? "?";
      menus.push({
        path: `${letter}/${label}`,
        label,
        groupLetter: letter,
        groupName,
        groupTitle,
        button: asString(e.button) ?? "",
        rights: asStringArray(e.rights),
        form: asString(e.form),
      });
    }
  }

  const forms: AppForm[] = [];
  const formsRaw = asRecord(root.forms) ?? {};
  for (const [name, value] of Object.entries(formsRaw)) {
    const f = asRecord(value);
    if (f === null) continue;
    const tables = asRecord(f.tables) ?? {};
    const formMenus = asStringArray(f.menus);
    const rawTitle = (asString(f.title) ?? "").replace(/^::\[\s*/, "").replace(/\s*\]::$/, "").trim();
    forms.push({
      name,
      title: rawTitle === "" || /^about program$/i.test(rawTitle) ? (formMenus[0]?.split("/")[1] ?? name) : rawTitle,
      file: asString(f.file) ?? "",
      package: asString(f.package) ?? "",
      menus: formMenus,
      rights: asStringArray(f.rights),
      actions: asStringArray(f.actions),
      popup: (Array.isArray(f.popup) ? f.popup : []).flatMap((entry) => {
        const item = asRecord(entry);
        if (item === null) return [];
        const path = asString(item.path);
        return path === null ? [] : [{ path, form: asString(item.form) }];
      }),
      tables: { read: asStringArray(tables.read), write: asStringArray(tables.write) },
    });
  }

  const rights: AppRight[] = [];
  for (const [name, value] of Object.entries(asRecord(root.rights) ?? {})) {
    const r = asRecord(value) ?? {};
    rights.push({ name, menus: asStringArray(r.menus), forms: asStringArray(r.forms) });
  }

  const toolbar = (Array.isArray(root.toolbar) ? root.toolbar : []).flatMap((entry) => {
    const item = asRecord(entry);
    if (item === null) return [];
    const label = asString(item.label);
    return label === null ? [] : [{ label, form: asString(item.form) }];
  });

  return {
    source: {
      commit: asString(source.commit) ?? "unknown",
      generatedAt: asString(source.generatedAt) ?? "",
      root: asString(source.root) ?? repoRoot,
    },
    menus,
    toolbar,
    forms,
    rights,
    flows: [],
    synonyms: [],
  };
};

const META = /```json meta\s*\n([\s\S]*?)\n```/;

/** One flow doc: a `json meta` block, then `### step` headings with **Menu:** / **Form:** / **Tabel:**. */
export const parseFlowDoc = (text: string, file: string): AppFlow | null => {
  const metaText = META.exec(text)?.[1];
  const meta = metaText === undefined ? null : asRecord((() => {
    try {
      return JSON.parse(metaText);
    } catch {
      return null;
    }
  })());

  const sections = text.split(/^### /m).slice(1);
  const steps: AppFlowStep[] = sections.map((section) => {
    const lines = section.split("\n");
    const title = (lines[0] ?? "").trim().replace(/^\d+[.)]\s*/, "");
    const field = (name: string) => {
      const line = lines.find((l) => l.toLowerCase().includes(`**${name.toLowerCase()}:**`));
      return line?.replace(/^-?\s*\*\*[^*]+\*\*:?\s*/, "").trim() ?? null;
    };
    const menuLine = field("Menu") ?? "";
    // Steps often write "`A/Rawat Jalan` (form `DlgKasirRalan`)"; keep just the paths.
    const menus = [...menuLine.matchAll(/`([A-T]\/[^`]+)`/g)].flatMap((match) => (match[1] === undefined ? [] : [match[1]]));
    const formInLine = /\(form `([^`]+)`\)/.exec(section)?.[1] ?? null;
    return {
      title,
      menu:
        menus.length > 0
          ? menus.join(" / ")
          : (() => {
              const raw = field("Menu");
              return raw !== null && /^[A-T]\//.test(raw) ? raw : null;
            })(),
      form: field("Form") ?? formInLine,
      tables: field("Tabel"),
    };
  });

  const id = asString(meta?.id) ?? NodePath.basename(file, ".md");
  return {
    id,
    title: asString(meta?.title) ?? (text.match(/^#\s+(.+)$/m)?.[1] ?? id),
    keywords: asStringArray(meta?.keywords),
    menus: asStringArray(meta?.menus),
    forms: asStringArray(meta?.forms),
    file,
    steps,
    text: text.replace(META, "").slice(0, 20_000),
  };
};

/** The hand-written synonym list next to index.json (optional). */
export const parseSynonyms = (text: string): ReadonlyArray<AppSynonym> => {
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    return [];
  }
  if (!Array.isArray(raw)) return [];
  return raw.flatMap((entry) => {
    const e = asRecord(entry);
    if (e === null) return [];
    const note = asString(e.note) ?? "";
    const terms = asStringArray(e.terms);
    if (terms.length === 0) return [];
    return [
      {
        terms,
        menus: asStringArray(e.menus),
        forms: asStringArray(e.forms),
        tables: asStringArray(e.tables),
        shortcut: asString(e.shortcut),
        note,
      },
    ];
  });
};

/** Reads index.json plus every `flows/*.md` and `synonyms.json` next to it. */
export const loadAppDocs = async (indexPath: string, repoRoot: string): Promise<AppDocsService> => {
  const index = await readFile(indexPath, "utf8").catch(() => "");
  if (index === "") return EMPTY;
  const base = parseAppIndex(index, repoRoot);
  const synonyms = parseSynonyms(await readFile(NodePath.join(NodePath.dirname(indexPath), "synonyms.json"), "utf8").catch(() => ""));
  const dir = NodePath.join(NodePath.dirname(indexPath), "flows");
  const names = await readdir(dir).catch(() => [] as string[]);
  const flows: AppFlow[] = [];
  for (const name of names.filter((n) => n.endsWith(".md") && n !== "README.md").toSorted()) {
    const text = await readFile(NodePath.join(dir, name), "utf8").catch(() => "");
    const flow = text === "" ? null : parseFlowDoc(text, NodePath.relative(repoRoot, NodePath.join(dir, name)));
    if (flow !== null) flows.push(flow);
  }
  return { ...base, flows, synonyms };
};

/** Docs from text (tests, fixtures). */
export const makeAppDocs = (
  index: string,
  flows: ReadonlyArray<{ readonly name: string; readonly text: string }> = [],
  synonyms: ReadonlyArray<AppSynonym> = [],
): AppDocsService => ({
  ...parseAppIndex(index, "test"),
  synonyms,
  flows: flows.flatMap((flow) => {
    const parsed = parseFlowDoc(flow.text, `docs/khanza-app/flows/${flow.name}`);
    return parsed === null ? [] : [parsed];
  }),
});

/** Docs from text (tests), as a Layer. */
export const appDocsLayer = (index: string, flows: ReadonlyArray<{ readonly name: string; readonly text: string }> = [], synonyms: ReadonlyArray<AppSynonym> = []) =>
  Layer.succeed(AppDocs, makeAppDocs(index, flows, synonyms));

export const AppDocsLive = Layer.effect(
  AppDocs,
  Effect.gen(function* () {
    const path = yield* AppDocPathConfig;
    return yield* Effect.promise(() => loadAppDocs(path, NodePath.resolve(import.meta.dirname, "../../../..")));
  }),
);
